From 6c24d1de2fc459d514631dbc0c3ebdafe7ca3463 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:42:30 +0100
Subject: [PATCH] RecentlyUsedEventSpy: only look up applications of new
 bookmarks

Each time recently-used.xbel changed, the plugin looked up the
application of every bookmark in it, although only new bookmarks are
used. Adding many files in a row kept a core busy; skip the old ones.

BUG: 470026
---
 .../plugins/recentlyused-eventspy/RecentlyUsedEventSpy.cpp | 7 +++++--
 1 file changed, 5 insertions(+), 2 deletions(-)

diff --git a/src/service/plugins/recentlyused-eventspy/RecentlyUsedEventSpy.cpp b/src/service/plugins/recentlyused-eventspy/RecentlyUsedEventSpy.cpp
index 7624e1bc..eca1c185 100644
--- a/src/service/plugins/recentlyused-eventspy/RecentlyUsedEventSpy.cpp
+++ b/src/service/plugins/recentlyused-eventspy/RecentlyUsedEventSpy.cpp
@@ -74,6 +74,9 @@ void RecentlyUsedEventSpyPlugin::fileUpdated(const QString &filename)
     QXmlStreamReader reader(&file);
     QList<Bookmark> bookmarks;
     Bookmark current;
+    const auto accessedSinceLastRun = [this](const Bookmark &mark) {
+        return mark.added > m_lastUpdate || mark.modified > m_lastUpdate || mark.visited > m_lastUpdate;
+    };
     while (!reader.atEnd()) {
         const auto token = reader.readNext();
         if (token == QXmlStreamReader::StartElement) {
@@ -88,7 +91,7 @@ void RecentlyUsedEventSpyPlugin::fileUpdated(const QString &filename)
                 current.visited = QDateTime::fromString(visited, Qt::ISODate);

                 // application for the current bookmark
-            } else if (reader.qualifiedName() == QLatin1String("bookmark:application")) {
+            } else if (reader.qualifiedName() == QLatin1String("bookmark:application") && accessedSinceLastRun(current)) {
                 Application app;

                 QString exec = reader.attributes().value("exec").toString();
@@ -138,7 +141,7 @@ void RecentlyUsedEventSpyPlugin::fileUpdated(const QString &filename)

     // then find the files that were accessed since last run
     for (const Bookmark &mark : std::as_const(bookmarks)) {
-        if (mark.added > m_lastUpdate || mark.modified > m_lastUpdate || mark.visited > m_lastUpdate) {
+        if (accessedSinceLastRun(mark)) {
             addDocument(mark.href, mark.latestApplication(), mark.mimetype);
         }
     }
-- 
